const IMAGES = {
  logo: "data:image/jpeg;base64,",
  products: ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"]
};

document.getElementById('brandLogo').src = IMAGES.logo;
document.getElementById('footerLogo').src = IMAGES.logo;

const products = [
  {name:'Signature Soy Candle', note:'Soft floral fragrance · hand-poured', price:'€18'},
  {name:'Herbst Glow Candle', note:'Warm seasonal mood · elegant finish', price:'€22'},
  {name:'Floral Gift Candle', note:'A thoughtful little gift', price:'€24'},
  {name:'Tigleo Classic', note:'Minimal ivory · timeless scent', price:'€20'},
  {name:'Cozy Home Candle', note:'Warm light for slow evenings', price:'€26'},
  {name:'Gift Set', note:'Curated candles for special moments', price:'€32'}
];

function productCards(limit=6){
 return products.slice(0,limit).map((p,i)=>`
  <article class="card">
    <img src="${IMAGES.products[i % IMAGES.products.length]}" alt="${p.name}">
    <div class="card-body">
      <h3>${p.name}</h3>
      <p>${p.note}</p>
      <span class="price">${p.price}</span>
    </div>
  </article>`).join('');
}

const app = document.getElementById('app');

function render(page){
 window.scrollTo({top:0,behavior:'smooth'});
 if(page==='home') app.innerHTML = `
  <section class="page hero">
    <div>
      <div class="eyebrow">Handmade · Soy Wax · NRW</div>
      <h1>Small candles.<br><span>Beautiful</span> moments.</h1>
      <p class="lead">Hand-poured candles made with care, warmth and a little bit of magic. Discover soft scents and thoughtful pieces made for your home or someone special.</p>
      <div class="actions">
        <button class="btn" data-page="shop">Explore collection</button>
        <button class="btn alt" data-page="order">Order a candle</button>
      </div>
    </div>
    <div class="hero-art">
      <img src="${IMAGES.logo}" alt="Tigleo Candles">
      <div class="seal">made with ♡</div>
    </div>
  </section>
  <section class="page" style="padding-top:10px">
    <div class="section-head"><div><div class="eyebrow">The collection</div><h2>Made to be gifted.</h2></div><p class="lead">Simple, elegant candles for birthdays, cozy evenings, celebrations and little everyday moments.</p></div>
    <div class="grid">${productCards(3)}</div>
    <div class="features">
      <div class="feature"><div class="icon">🕯️</div><b>Hand-poured</b><p>Made carefully in small batches.</p></div>
      <div class="feature"><div class="icon">🌸</div><b>Soft & elegant</b><p>Designed to feel beautiful in your space.</p></div>
      <div class="feature"><div class="icon">🎁</div><b>Gift-ready</b><p>Perfect for someone you love.</p></div>
    </div>
  </section>`;
 else if(page==='shop') app.innerHTML = `
  <section class="page">
    <div class="eyebrow">Tigleo collection</div><h2>Find your glow.</h2>
    <p class="lead">A curated demo collection inspired by Tigleo's soft, warm aesthetic.</p>
    <div class="grid">${productCards(6)}</div>
  </section>`;
 else if(page==='story') app.innerHTML = `
  <section class="page story">
    <div class="story-box"><div class="eyebrow">Our story</div><h2>Made slowly.<br>Made lovingly.</h2><p>Tigleo Candles is a handmade candle studio from NRW, creating warm little pieces for homes, celebrations and thoughtful gifts.</p><p>Every candle is designed to feel calm, personal and special — from the first light to the last glow.</p></div>
    <div><div class="eyebrow">Why Tigleo?</div><h2>A little warmth goes a long way.</h2><p class="lead">From seasonal inspiration to floral details, each collection is created around the feeling a candle can bring into a room.</p><div class="features"><div class="feature"><b>Handmade</b><p>Small-batch care.</p></div><div class="feature"><b>Personal</b><p>Made for gifting.</p></div><div class="feature"><b>Beautiful</b><p>Soft, timeless design.</p></div></div></div>
  </section>`;
 else if(page==='order') app.innerHTML = `
  <section class="page">
    <div class="order-box">
      <div class="eyebrow">Custom order</div><h2>Let's make it special.</h2>
      <p class="lead">Tell us what you have in mind. This is a demo order form — the real version can connect directly to Instagram or WhatsApp.</p>
      <form id="orderForm">
        <input required placeholder="Your name">
        <input required type="email" placeholder="Email address">
        <select><option>Choose a candle</option><option>Signature Soy Candle</option><option>Herbst Glow Candle</option><option>Floral Gift Candle</option><option>Gift Set</option></select>
        <textarea placeholder="Tell us about your preferred scent, colour or gift idea..."></textarea>
        <button class="btn" type="submit">Send enquiry ♡</button>
      </form>
    </div>
  </section>`;
}

document.addEventListener('click', e=>{
 const btn=e.target.closest('[data-page]');
 if(btn){ document.getElementById('nav').classList.remove('open'); render(btn.dataset.page); }
});
document.querySelector('.menu-btn').addEventListener('click',()=>document.getElementById('nav').classList.toggle('open'));
document.addEventListener('submit',e=>{
 if(e.target.id==='orderForm'){
   e.preventDefault();
   const t=document.getElementById('toast'); t.textContent='Thank you ♡ Your enquiry is ready to send.'; t.classList.add('show');
   setTimeout(()=>t.classList.remove('show'),2800); e.target.reset();
 }
});
render('home');
